(window.TNQ=window.TNQ||[]).push({"terms":{"청소년상담복지센터":{"d":"지역사회를 기반으로 청소년 상담과 복지를 제공하는 대표적인 청소년상담 기관.","r":["청소년동반자"]},"비밀유지":{"d":"상담에서 알게 된 내용을 밖으로 알리지 않는 것으로 예외상황은 미리 고지한다.","r":[]},"스마트폰 과의존":{"d":"이용 조절력이 감소하고 현저성이 증가해 문제적 결과를 경험하는 상태.","r":["현저성"]},"현저성":{"d":"특정 대상이 생각과 행동에서 두드러지게 중요해지는 정도.","r":["스마트폰 과의존"]},"청소년동반자":{"d":"위기청소년을 돕기 위해 지역사회에서 운영하는 프로그램.","r":[]},"또래상담":{"d":"청소년폭력 예방을 위해 또래가 상담자로 나서는 프로그램.","r":[]},"채팅상담":{"d":"사이버상담 유형의 하나로 내담자와 동시적인 상호작용이 가능한 상담.","r":[]},"화상상담":{"d":"영상으로 서로를 보며 진행하는 사이버상담 방식.","r":["채팅상담"]},"위기개입":{"d":"위기에 처한 사람의 안정을 되찾도록 서둘러 돕는 개입.","r":[]},"단어연상검사":{"d":"제시한 단어에서 떠오르는 말을 하게 해 무의식을 탐색하는 정신역동적 기법.","r":["개인 무의식"]},"개인 무의식":{"d":"억압된 기억이나 사고, 감정이 저장되는 무의식.","r":["단어연상검사"]},"상보적":{"d":"서로 맞서지 않고 부족한 부분을 채워 주는 관계.","r":[]},"전체론적":{"d":"인간을 부분으로 쪼개지 않고 하나의 전체로 보는 관점.","r":[]},"자아상태":{"d":"교류분석에서 성격구조와 기능을 파악하는 데 쓰는 분석 단위.","r":[]},"드라마 삼각형":{"d":"카프만이 게임분석을 위해 고안한 구조.","r":[]},"금지령":{"d":"각본분석에서 굴딩이 목록으로 제시한 부정적 메시지.","r":[]},"소거":{"d":"강화를 없애 학습된 행동이 줄어들게 하는 일.","r":[]},"스토아 학파":{"d":"고대 철학의 한 학파로 REBT의 근원을 이룬다.","r":[]},"쾌락주의":{"d":"쾌락을 추구하는 것을 중시하는 입장으로 REBT에서는 책임이 따르는 것으로 본다.","r":[]},"전행동":{"d":"현실치료에서 내담자의 행동을 총체적으로 가리키는 개념.","r":[]},"도덕적 딜레마":{"d":"도덕적 가치가 서로 부딪쳐 선택하기 어려운 상황.","r":["콜버그 이론"]},"콜버그 이론":{"d":"도덕성이 단계를 거쳐 발달한다고 보는 이론.","r":["도덕적 딜레마"]},"명료화":{"d":"모호한 표현을 명확하게 하기 위한 질문 형태의 기술.","r":[]},"구조화":{"d":"상담자와 내담자의 역할을 명료화하고 상담 진행과정에 합의하는 일.","r":[]},"비밀보장":{"d":"상담 내용을 외부에 알리지 않는 것으로 그 의미와 한계를 안내해야 한다.","r":["비밀유지"]}},"notes":{"R. Wubbolding: 지지적인 상담환경을 강조하여 구체적인 권장사항을 제시하였다":"우볼딩은 지지적인 상담환경을 강조하면서 구체적 권장사항을 내놓았습니다.","‘위기청소년 발견’, ‘상담개입’, ‘통합서비스 제공’이라는 세 가지 운영 모듈을 가지고 있다":"운영은 위기청소년 발견, 상담개입, 통합서비스 제공의 세 모듈로 이루어집니다.","‘책임을 동반한 쾌락주의’, ‘인본주의’, ‘합리성’의 개념이 포함되어 있다":"REBT의 철학적 토대에는 책임을 동반한 쾌락주의와 인본주의, 합리성이 들어 있습니다.","「청소년복지 지원법」에 따라 설치ㆍ운영하고 있다":"청소년상담복지센터는 청소년복지 지원법을 근거로 설치하고 운영합니다.","가설적 상황보다는 실제 상황을 적용하여 여성이 직면하는 도덕적 딜레마를 제시하고자 하였다":"가정된 상황이 아닌 실제 상황으로 여성이 직면하는 도덕적 딜레마를 드러내려 했습니다.","각본분석에 의한 금지령 목록을 제시하고 있다":"굴딩은 각본분석에서 나온 금지령을 목록으로 정리해 제시했습니다.","강화와 소거 등의 원리를 사용하여 내담자의 행동을 수정한다":"강화를 주거나 소거하는 원리로 행동을 바꿉니다.","개인의 일관된 성격구조로 생애초기에 형성된다":"생활양식은 한 사람의 일관된 성격구조이며 어릴 때 일찍 만들어집니다.","개인적 능력감과 사회적 능력감을 기르도록 돕는다":"스스로 할 수 있다는 능력감을 개인과 사회 두 차원에서 키웁니다.","검증되지 않고 훈련받지 않은 상담기법의 오ㆍ남용을 하지 않는다":"효과가 검증되지 않았거나 훈련받지 않은 기법을 함부로 쓰지 않습니다.","게임분석을 위해 드라마 삼각형을 고안하였다":"카프만은 게임분석에 쓰려고 드라마 삼각형을 만들었습니다.","경제적, 사회적, 심리적으로 위기에 처한 청소년의 안정적 생활을 지원한다":"경제적·사회적·심리적 위기에 놓인 청소년이 안정되게 생활하도록 지원합니다.","고대 로마의 에픽테투스(Epictetus) 사상의 영향을 받았다":"REBT는 고대 로마 철학자 에픽테투스의 사상을 이어받았습니다.","과도한 스마트폰 이용으로 인해 스마트폰에 대한 현저성이 증가하고 이용 조절력이 감소해 문제적 결과를 경험하는 상태이다":"스마트폰이 생활에서 두드러지게 커지고 이용을 조절하기 어려워져 문제가 생기는 상태가 과의존입니다.","구체적인 상담개입의 방향을 제시해주는 역할을 한다":"상담개입이 어느 방향으로 가야 할지 구체적으로 알려 줍니다.","내담자가 두려워하는 자극에 노출시키되 강박행동을 하지 못하게 하는 기법이다":"두려운 자극에 직접 노출시키면서 강박행동은 못 하게 막는 기법입니다.","내담자가 진술한 내용을 상담자의 말로 바꾸어 기술하는 것으로 내담자로 하여금 자신이 한 말에 주의를 기울이게 한다":"재진술은 내담자의 말을 상담자의 말로 바꿔 전달해 자기가 한 말에 주의를 기울이게 합니다.","내담자가 표현한 감정을 상담자가 다른 말로 부연해주는 것으로 내담자로 하여금 이해받고 있다는 인식을 갖게 한다":"감정반영은 내담자가 표현한 감정을 다른 말로 풀어 줘서 이해받는다는 느낌을 갖게 합니다.","내담자는 자신의 정서와 행동에 대한 책임이 있다":"현실치료는 내담자가 자기 정서와 행동에 책임을 진다고 봅니다.","내담자에게 상담을 거부하거나 개입방식의 변경을 거부할 권리를 보장해 주어야 한다":"내담자는 상담을 거절할 권리와 개입 방식 변경을 거절할 권리를 가집니다.","내담자에 대한 잠정적인 가설이다":"사례개념화는 내담자에 대해 잠정적으로 세워 두는 가설입니다.","내담자에 대한 정보가 추가될 때마다 수정, 보완할 수 있다":"새 정보가 들어오면 그때마다 고치고 보태어 갈 수 있습니다.","내담자의 경험, 행동, 사고에 대한 상담자의 경험 또는 감정을 구두로 전달하는 것이다":"즉시성은 내담자의 경험과 행동에 대한 상담자 자신의 경험이나 감정을 말로 전하는 것입니다.","내담자의 말과 행동에 집중해서 보고 듣는 것으로 내담자가 생각이나 감정을 자유롭게 표현하게 한다":"경청은 내담자의 말과 행동에 집중해 보고 들음으로써 생각과 감정을 자유롭게 표현하게 돕습니다.","내담자의 메시지 이면에 있는 감정을 표면적으로 드러내는 것이다":"반영은 메시지 뒤에 숨은 감정을 겉으로 드러내 보여 주는 기술입니다.","내담자의 문제행동에 대한 분석이 이루어지면 내담자와 함께 구체적인 상담목표를 설정한다":"문제행동을 분석한 뒤에 내담자와 함께 구체적 상담목표를 정합니다.","내담자의 부적응 행동수정을 목표로 한다":"행동주의 상담은 내담자의 부적응 행동을 고치는 것을 목표로 합니다.","내담자의 신분을 확인할 방법이 있어야 한다":"그러려면 내담자가 누구인지 파악할 수단을 마련해 두어야 합니다.","내담자의 욕구를 탐색하고 원하는 것을 얻기 위해 무엇을 해왔는지 파악한다":"내담자의 욕구와 그것을 얻으려고 지금까지 해 온 일을 파악합니다.","내담자의 자기탐색을 촉진하고 내담자 또는 관계에 초점을 유지하기 위해 사용한다":"즉시성은 자기탐색을 돕고 초점을 내담자나 관계에 두기 위해 씁니다.","내담자의 자아상태 분석을 통해 성격구조와 기능을 파악한다":"교류분석은 자아상태를 분석해 내담자의 성격구조와 기능을 이해합니다.","내담자의 작은 변화도 민감하게 지각하고, 상담에 대한 태도와 생각과 감정을 다룬다":"작은 변화에도 민감하게 반응하면서 상담에 대한 태도와 생각, 감정을 다룹니다.","내담자의 진술 중 핵심내용을 상담자의 언어로 바꾸어 되풀이해 주는 기술이다":"요약은 진술의 핵심을 상담자의 말로 추려 되풀이해 주는 기술입니다.","내담자의 현재 행동에 초점을 두고 행동의 효과성에 따라":"현재 행동에 초점을 두고 그 행동이 효과가 있는지에 따라 판단합니다.","내면의 갈등을 억압하기 위한 것인지 살펴본다":"저항이 내면의 갈등을 억누르려는 것인지 따져 봅니다.","내면화된 여성 역할 메시지를 확인하도록 돕는다":"자기도 모르게 받아들인 여성 역할 메시지를 알아차리도록 돕습니다.","다문화 배경을 가진 내담자를 위한 검사선택시 내담자의 사회문화적 맥락을 신중히 고려하였다":"다문화 내담자에게 쓸 검사를 고를 때는 그의 사회문화적 맥락을 신중하게 헤아립니다.","단어연상검사, 꿈 분석, 증상 분석 등의 기법을 사용한다":"정신역동적 상담은 단어연상검사와 꿈 분석, 증상 분석으로 무의식을 다룹니다.","대면상담과 마찬가지로 사이버상담에서도 관계형성 및 구조화는 중요하다":"얼굴을 맞대지 않아도 사이버상담에서 관계 형성과 구조화는 빠뜨릴 수 없습니다.","대표적인 지역사회 기반의 청소년상담 기관으로 청소년상담복지센터가 있다":"지역사회를 기반으로 하는 대표 상담 기관은 청소년상담복지센터입니다.","모호한 표현을 명확하게 하기 위한 질문 형태의 기술로 내담자가 미처 생각하지 못했던 측면을 다시 생각해 보게 한다":"명료화는 모호한 표현을 분명하게 하려고 질문하는 기술로 미처 생각하지 못한 면을 다시 보게 합니다.","목적은 내담자의 문제를 해결하기 위한 효과적인 계획을 세우는 데 있다":"내담자의 문제를 푸는 효과적인 계획을 세우는 것이 궁극의 목적입니다.","목표와 성취를 위한 기초가 된다":"일차적 열등감은 부정적 결과만 낳지 않고 목표와 성취를 향한 기초가 됩니다.","목표행동에 접근하는 반응을 강화하여 새로운 행동을 단계적으로 습득하게 한다":"행동조형은 목표에 가까워지는 반응을 하나씩 강화해 새 행동을 단계별로 익히게 합니다.","문제해결 중심으로 진행되며 대면상담으로 연계하는 역할을 한다":"전화상담은 문제해결에 맞춰 진행하고 필요하면 대면상담으로 이어 주는 통로입니다.","바이힝거(H. Vaihinger)의 영향을 받은 것이다":"가상적 목표라는 아이디어는 바이힝거의 철학에서 영향을 받았습니다.","발달단계를 고려하여 프로그램을 개발하고 실행한다":"청소년의 발달단계에 맞추어 프로그램을 만들고 운영합니다.","변화를 시도하는 과정에서 걱정이나 답답함이 있는지 탐색한다":"변화를 시도하며 느끼는 걱정이나 답답함이 있는지 탐색합니다.","부모에게 알리고 싶지 않은 이유를 탐색한다":"내담자가 부모에게 알리기를 꺼리는 까닭을 먼저 탐색합니다.","부적응 행동이 습득되고 유지되는 과정을 학습이론에 근거하여 설명한다":"부적응 행동이 생기고 계속되는 과정을 학습이론으로 설명합니다.","불안이나 스트레스를 겪고 있는 내담자에게 적용한다":"이완훈련은 불안이나 스트레스로 힘들어하는 내담자에게 쓰는 기법입니다.","비밀유지 예외상황에 대해 고지한다":"비밀이 지켜지지 않을 수 있는 예외 상황을 내담자에게 미리 알립니다.","사이버상담 시 위기개입 등의 상황에 대비하기 위해":"사이버상담에서는 위기개입이 필요한 일이 생길 것을 미리 대비해야 합니다.","사이버상담 유형 중 채팅상담은 내담자와 동시적인 상호작용이 가능하다":"채팅상담은 내담자와 같은 시간에 주고받는 동시적 상호작용이 가능한 유형입니다.","사회적 신념이 자신에게 어떻게 부정적으로 영향을 주는지 이해하도록 돕는다":"사회의 신념이 자신에게 어떤 해를 주는지 깨닫도록 돕습니다.","삶의 문제에 대해 자신감이 없어 매사에 소극적인 유형이다":"회피형은 삶의 문제 앞에서 자신감이 없어 매사에 소극적인 유형입니다.","상담비용은 내담자의 재정 상태 등을 고려하여 합리적으로 책정한다":"비용은 내담자의 형편을 감안해 합리적인 수준으로 정합니다.","상담시간에 오지 못할 경우 연락하는 방법에 대해 상의한다":"약속 시간에 못 올 때 연락하는 방법도 미리 상의해 둡니다.","상담에 대한 수동적 거부 행동은 아닌지 점검한다":"상담을 수동적으로 거부하는 행동은 아닌지 점검합니다.","상담자는 비밀보장의 의미와 한계에 대한 정보를 안내한다":"비밀보장이 무슨 뜻이고 어디까지인지를 상담자가 안내합니다.","상담자들은 종종 이 반응이 내담자를 화나게 만들지 않을까 걱정하기도 한다":"상담자들은 이런 반응이 내담자를 화나게 할까 봐 망설이기도 합니다.","상담자와 내담자의 역할을 명료화한다":"구조화에서는 상담자와 내담자가 각자 맡을 역할을 분명히 합니다.","상담자의 개인적 생각이나 경험을 내담자와 나누는 것이다":"자기개방은 상담자가 개인적인 생각이나 경험을 내담자와 나누는 기법입니다.","상담 진행과정에 대해 합의하는 과정이다":"구조화는 상담이 어떻게 진행될지 두 사람이 합의하는 과정이기도 합니다.","상담회기 중 특정 사건, 내담자에 대한 상담자 반응에 초점을 맞출 수 있다":"즉시성을 쓰는 순간에는 회기에서 벌어진 사건이나 상담자 자신의 반응을 화제로 삼습니다.","상호억제 기제를 사용하여 불안이나 공포를 감소시키는 데 사용한다":"체계적 둔감화는 상호억제 원리를 활용해 불안과 공포를 줄입니다.","새로운 전행동(total behavior)을 선택하도록 한다":"효과가 없으면 내담자가 새로운 전행동을 고르도록 돕습니다.","생물학적 변화로 인해 발달심리적 위기를 겪는다":"청소년은 신체의 생물학적 변화 때문에 발달심리적 위기를 겪습니다.","스마트폰 과의존 유형에는 SNS, 게임, 음란물, 도박, 검색 등이 있다":"과의존 대상은 SNS와 게임뿐 아니라 음란물, 도박, 검색까지 다양합니다.","스마트폰 및 인터넷 환경의 발달로 채팅상담과 화상상담 등이 활발해졌다":"기기와 인터넷이 발달하면서 채팅상담과 화상상담 같은 방식이 널리 쓰이게 되었습니다.","스마트폰 사용에 대한 통제력을 상실한 상태로 전문적인 도움이 필요하다":"고위험 사용자군은 통제력을 잃은 단계라서 전문적인 도움이 필요합니다.","스마트폰을 사용하지 못하면 초조하고 불안함을 느끼는 현상이다":"금단은 스마트폰을 쓰지 못할 때 초조하고 불안해지는 반응입니다.","스토아 학파에서 근원을 찾을 수 있다":"REBT의 사상적 뿌리는 스토아 학파까지 거슬러 올라갑니다.","스트레스 상황에서 적절성 여부와 상관없이 반복적으로 사용된다":"라켓감정은 상황에 맞든 안 맞든 스트레스를 받으면 되풀이해 쓰는 감정입니다.","실험적 연구에서 밝혀진 학습원리를 심리치료에 응용한 것이다":"실험 연구로 밝혀진 학습원리를 심리치료에 가져다 쓴 것입니다.","억압된 기억이나 사고, 감정은 개인 무의식에 저장된다":"억눌린 기억과 사고, 감정은 개인 무의식에 저장되어 있다고 봅니다.","여성의 도덕성이 일반적으로 3단계에 도달하는 반면, 남성의 도덕성이 4단계에 도달한다는 결과는 여성의 결함이 아니라 콜버그 이론의 결함이라고 주장한다":"여성이 3단계에, 남성이 4단계에 이르는 결과는 여성의 결함이 아니라 콜버그 이론의 결함이라고 주장합니다.","여성의 착한 면으로 여겨지는 동정심과 돌봄과 같은 특성은 여성의 도덕성 발달에 있어서 불리한 조건으로 작용한다고 보았다":"착하다고 여겨지는 동정심과 돌봄의 특성이 오히려 도덕성 발달에서 불리하게 작용한다고 보았습니다.","완전함을 향해 나아가는 전체론적인 존재이다":"아들러는 인간을 완전함을 향해 나아가는 분리되지 않는 전체적 존재로 봅니다.","외향적 사고와 내향적 사고는 대립되는 것이 아니라 상보적이다":"외향적 사고와 내향적 사고는 서로 맞서지 않고 보완하는 관계입니다.","우울감이 높은 청소년은 인터넷이나 스마트폰에 중독될 가능성이 높다":"우울감이 큰 청소년일수록 인터넷이나 스마트폰에 중독되기 쉽습니다.","위기개입 및 자립을 지원하여 건전한 발달과 성장을 돕는다":"위기개입과 자립 지원은 청소년이 건전하게 발달하고 자라도록 하려는 수단입니다.","위기 상황에 처한 청소년에게 즉각적인 도움을 제공할 수 있다":"전화는 곧바로 연결되므로 위기에 놓인 청소년에게 즉각 도움을 줄 수 있습니다.","위기청소년에 대한 지원 의뢰가 있을 경우 최우선적으로 지원하도록 상호 협력하여야 한다":"위기청소년을 지원해 달라는 의뢰가 오면 연계기관은 서로 협력해 가장 먼저 지원합니다.","위기 청소년을 돕기 위한 청소년동반자 프로그램이 있다":"청소년동반자는 위기청소년과 함께하며 돕는 지역사회 프로그램입니다.","위기청소년을 지원하기 위한 자발적인 지역주민모임이 있다":"지역주민이 스스로 모여 위기청소년을 돕는 모임도 지역사회 자원입니다.","인간의 삶에 혼란을 가져올 수 있다":"이 상호작용이 잘못되면 삶에 혼란이 올 수 있습니다.","인간의 행동은 환경과의 상호작용에 의해 이루어진다고 본다":"행동은 개인 안에서만 생기지 않고 환경과 주고받는 가운데 이루어진다고 봅니다.","인지, 정서, 행동이 상호작용하는 과정":"REBT는 인지와 정서와 행동이 서로 영향을 주고받는 과정에 주목합니다.","일상에서 당면한 문제 해결과 예방을 위해 교육을 실시한다":"문제가 생긴 뒤 해결뿐 아니라 생기지 않게 막는 예방도 교육으로 다룹니다.","자살을 생각하게 된 어려움이 무엇인지 구체적으로 살펴본다":"자살을 떠올리게 한 어려움이 무엇인지 구체적으로 묻고 파악합니다.","자신의 생활에 미치는 사회적 요인을 평가하도록 돕는다":"여성주의 상담은 내담자 삶에 영향을 주는 사회적 요인을 따져 보게 합니다.","정체성 형성에 있어, 전통적인 심리학에서 바라보는 여성들의 관계에 대한 관점을 비평하였다":"전통 심리학이 여성의 관계를 바라보는 관점을 정체성 형성 논의에서 비판했습니다.","죽음을 생각할 만큼 힘든 내담자의 마음을 공감한다":"죽음을 떠올릴 정도로 힘든 내담자의 마음에 먼저 공감합니다.","중년기 이후에는 자기의 방향이 내부로 향하여 자아는 다시 자기에 통합되면서 성격 발달이 이루어진다":"중년기부터는 관심이 내면으로 향하며 자아가 자기에 다시 통합되는 쪽으로 성격이 발달합니다.","지방고용노동청 및 지청이 포함되어 있다":"필수연계기관에는 지방고용노동청과 그 지청도 들어갑니다.","지역사회기반으로 통합서비스를 제공하기 위한 시스템이다":"CYS-Net은 지역사회를 바탕으로 통합서비스를 주기 위해 짠 체계입니다.","청소년 고용, 보호 기관 관련자도 상담 대상에 포함된다":"상담 대상은 청소년 본인만이 아니라 청소년을 고용하거나 보호하는 기관 관련자까지 넓습니다.","청소년 내담자에게 무력, 정신적 압력을 사용하지 않는다":"무력이나 정신적 압력으로 내담자를 움직이려 해서는 안 됩니다.","청소년들이 일상생활에서 직면하는 문제의 해결을 조력한다":"일상에서 마주치는 문제를 청소년이 해결하도록 돕는 것이 목표의 하나입니다.","청소년상담 1388을 통해 모바일상담이 가능하다":"1388을 통해 휴대전화로 하는 모바일상담도 받을 수 있습니다.","청소년상담사는 자신의 개인적 가치, 태도, 신념, 행위를 자각하고 내담자에게 자신의 가치를 강요하지 않는다":"상담사는 자기 가치를 먼저 자각하고 그것을 내담자에게 강요하지 않아야 합니다.","청소년에 대한 상담, 긴급구조, 보호, 의료지원 등을 지원한다":"이 체계로 상담과 긴급구조, 보호, 의료지원이 청소년에게 제공됩니다.","청소년을 둘러싼 적절하지 못한 환경을 개선한다":"상담 목표는 청소년 개인에 머물지 않고 주변의 부적절한 환경을 고치는 데까지 이릅니다.","청소년의 바람직한 발달을 추구하는 활동이다":"청소년상담은 문제 제거보다 바람직한 발달을 이끄는 활동이라는 특징이 있습니다.","청소년의 잠재가능성을 발현할 수 있도록 조력하는 전문적 활동이다":"상담은 숨은 가능성이 드러나게끔 전문성을 바탕으로 곁에서 거드는 활동입니다.","청소년의 잠재 가능성을 찾아 실현할 수 있도록 지원한다":"청소년상담은 청소년이 지닌 잠재 가능성을 찾아 실현하도록 돕는 데서 출발합니다.","청소년폭력 예방을 위한 또래상담 프로그램이 있다":"또래상담은 또래끼리 도우며 청소년폭력을 예방하려는 프로그램입니다.","특징은 익명성과 편의성 보장이며, 긴급한 위기상황에서 도움을 요청하는 수단이 될 수 있다":"익명이 보장되고 이용하기 편해 긴급한 위기에서 도움을 청하는 수단이 됩니다.","폭력이나 절도와 같은 심각한 범죄 뿐만 아니라 음주, 흡연 등과 같은 일탈행동도 포함한다":"청소년 비행은 중범죄는 물론 음주와 흡연 같은 일탈행동까지 아우릅니다.","학교폭력에는 사이버 따돌림과 음란 정보에 의해 정신적 피해를 주는 경우도 해당된다":"사이버 따돌림이나 음란 정보로 정신적 피해를 입히는 것도 학교폭력에 들어갑니다.","행동은 강화와 모방을 통해 학습된다고 본다":"이 접근은 행동이 강화와 모방으로 학습된다고 봅니다.","현재형으로 진술하여 지금-여기의 경험을 드러낸다":"현재형으로 말해서 지금-여기에서 일어나는 경험을 드러냅니다.","환경론을 강조하고 비합리적 충동적 욕구도 후천적인 조건화의 결과로 본다":"비합리적 충동도 타고난 것이 아니라 조건화로 얻은 결과로 본다는 환경론의 입장입니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
